function sr(kh: string) : string {
    let ms : boolean = true
    for (let oa : number = 0; oa <= 1; oa++) {
        if (!ms) {
            kh = kh + 8
        } else {
            kh = kh + 4
        }
        ms = !ms
    }
    return kh
}

